-- 启用租户 2009 店铺客服后，修复旧演示 FAQ 缺少 keywords/enabled 导致的反序列化失败。
SET @faq_json = CONVERT( USING utf8mb4);

UPDATE promotion_kefu_faq_config
SET draft_json = @faq_json,
    published_json = @faq_json,
    update_time = NOW()
WHERE tenant_id = 2009
  AND scope = 'SHOP'
  AND shop_id BETWEEN 940501 AND 940505;

SELECT shop_id, JSON_VALID(draft_json) AS draft_valid,
       JSON_LENGTH(draft_json) AS faq_count
FROM promotion_kefu_faq_config
WHERE tenant_id = 2009 AND scope = 'SHOP'
  AND shop_id BETWEEN 940501 AND 940505
ORDER BY shop_id;